sys_script_include.script:
var referenceQualifierUtils = Class.create();
referenceQualifierUtils.prototype = Object.extendsObject(gerateOTP,{
    initialize: function() {},

    getMyAssignmentGroups: function() {

        var groupsList = [];

        var getMyGrps = new GlideRecord('sys_user_grmember');
        getMyGrps.addEncodedQuery('user.sys_id=' + gs.getUserID());
        getMyGrps.query();
        while (getMyGrps.next()) {

            groupsList.push(getMyGrps.group.sys_id + '');


        }

       return groupsList.toString();

    },

    type: 'referenceQualifierUtils'
});
